query DiseaseDrugs($diseaseId: String!) {
  disease(efoId: $diseaseId) {
    id
    drugAndClinicalCandidates {
      count
      rows {
        maxClinicalStage
        drug {
          id
          name
          maximumClinicalStage
          parentMolecule { id name }
        }
        clinicalReports { url }
      }
    }
  }
}
